import asyncio

class TransientError(Exception):
    pass

async def retry(operation, attempts, sleep=asyncio.sleep):
    for index in range(attempts):
        try:
            return await operation()
        except Exception:
            await sleep(0.01 * (2 ** index))
    raise RuntimeError('operation failed')

