files.ttl_cache.py:
import time

class TTLCache:
    def __init__(self, loader, ttl, clock=time.monotonic):
        self.loader = loader
        self.ttl = ttl
        self.clock = clock
        self.entries = {}

    def get(self, key):
        value, loaded_at = self.entries.get(key, (None, 0))
        if not value or self.clock() - loaded_at > self.ttl:
            value = self.loader(key)
            self.entries[key] = (value, self.clock())
        return value

    def invalidate(self, key):
        del self.entries[key]

