import unittest
from stream_decoder import decode_chunks

class Tests(unittest.TestCase):
    def test_split_multibyte_characters(self):
        raw = 'A€雪B'.encode('utf-8')
        chunks = [raw[:2], b'', raw[2:4], raw[4:6], raw[6:]]
        self.assertEqual(decode_chunks(iter(chunks)), 'A€雪B')
