class Tests(unittest.TestCase):
    def test_dependencies_precede_dependents(self):
        graph = {'app': ['core', 'ui'], 'core': ['util'], 'ui': ['util'], 'util': []}
        original = {key: list(value) for key, value in graph.items()}
        order = build_order(graph)
        self.assertEqual(order, ['util', 'core', 'ui', 'app'])
        self.assertEqual(graph, original)
    def test_preserves_ready_insertion_order(self):
        self.assertEqual(build_order({'b': [], 'a': [], 'root': ['a', 'b']}), ['b', 'a', 'root'])
    def test_rejects_unknown_dependency(self):
        with self.assertRaises(ValueError):
            build_order({'app': ['missing']})
    def test_rejects_cycle(self):
        with self.assertRaises(ValueError):
            build_order({'a': ['b'], 'b': ['c'], 'c': ['a']})

