def apply_batch(state, operations):
    for operation in operations:
        action, key, *rest = operation
        if action == 'set':
            state[key] = rest[0]
        elif action == 'delete':
            del state[key]
        else:
            raise ValueError('unknown operation')
    return dict(state)

