import unittest
from store import apply_batch

class Tests(unittest.TestCase):
    def test_applies_in_order_and_returns_same_dict(self):
        state = {'a': 1, 'b': 2}
        result = apply_batch(state, [('set', 'a', 3), ('delete', 'b'), ('set', 'c', 4)])
        self.assertIs(result, state)
        self.assertEqual(state, {'a': 3, 'c': 4})
    def test_rolls_back_after_late_failure(self):
        marker = object()
        state = {'a': marker}
        with self.assertRaises(ValueError):
            apply_batch(state, [('set', 'a', 2), ('delete', 'missing')])
        self.assertEqual(state, {'a': marker})
    def test_rejects_bad_name_and_arity_transactionally(self):
        for operations in ([('move', 'a')], [('set', 'a')], [('set', 'a', 1, 2)], [('delete', 'a', 1)]):
            state = {'a': 0}
            with self.subTest(operations=operations):
                with self.assertRaises(ValueError):
                    apply_batch(state, operations)
                self.assertEqual(state, {'a': 0})

