export function reduceTabs(state, action) {
  if (action.type !== 'close') return { ...state };
  const index = state.tabs.findIndex(tab => tab.id === action.id);
  state.tabs.splice(index, 1);
  return { ...state, activeId: state.tabs[index - 1]?.id ?? null };
}

