import test from 'node:test';
import assert from 'node:assert/strict';
import { reduceTabs } from './tabState.js';

const state = () => ({ tabs: [{id:'a'}, {id:'b'}, {id:'c'}], activeId: 'b' });

test('closes active middle tab and selects next immutably', () => {
  const input = state(); const tabs = input.tabs;
  const result = reduceTabs(input, {type:'close', id:'b'});
  assert.deepEqual(result, {tabs:[{id:'a'}, {id:'c'}], activeId:'c'});
  assert.deepEqual(input, state());
  assert.equal(input.tabs, tabs);
});
test('closing inactive and unknown tabs preserves active tab', () => {
  assert.equal(reduceTabs(state(), {type:'close', id:'a'}).activeId, 'b');
  assert.deepEqual(reduceTabs(state(), {type:'close', id:'missing'}), state());
});
test('closing final active tab yields null', () => {
  assert.deepEqual(reduceTabs({tabs:[{id:'a'}], activeId:'a'}, {type:'close', id:'a'}), {tabs:[], activeId:null});
});
test('unknown action returns same state object', () => {
  const input = state();
  assert.equal(reduceTabs(input, {type:'noop'}), input);
});

